# SAVE ALL 15 FILES
# ================================================================

print("\n" + "="*60)
print("  SAVING HUMAN REFERENCE FILES")
print("="*60)

saved   = 0
for filename, content in references.items():
    filepath = os.path.join("evaluation/human_references", filename + ".txt")
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(content.strip())
    word_count = len(content.split())
    print(f"  Saved: {filename}.txt  ({word_count} words)")
    saved += 1

print(f"\n  Total saved : {saved}/15 files")
print(f"  Location    : evaluation/human_references/")
